INSERT INTO questions (id, text, type, options, correct_answer, explanation, subject, grade_level, difficulty, weight, created_at) VALUES ('q-gen-1780822217816-707', 'What is the capital city of Australia?', 'mcq', '["Sydney","Melbourne","Canberra","Brisbane"]', '2', 'Canberra was chosen as the capital in 1908 as a compromise between Sydney and Melbourne.', 'Geography', 8, 'medium', 1.5, '2026-10-12 17:20:01') ON CONFLICT DO NOTHING;
INSERT INTO questions (id, text, type, options, correct_answer, explanation, subject, grade_level, difficulty, weight, created_at) VALUES ('q-gen-1780822217815-128', 'Chlorophyll is the pigment responsible for giving plants their green color.', 'trueFalse', NULL, 'true', 'Chlorophyll is present in plant chloroplasts and absorbs light, reflecting green wavelengths.', 'Science', 8, 'easy', 1, '2026-10-12 17:20:01') ON CONFLICT DO NOTHING;
INSERT INTO questions (id, text, type, options, correct_answer, explanation, subject, grade_level, difficulty, weight, created_at) VALUES ('q-gen-1780822217815-274', 'Solve for x: 3x - 7 = 14', 'mcq', '["x = 5","x = 7","x = 9","x = 3"]', '1', 'Add 7 to both sides: 3x = 21, then divide by 3: x = 7.', 'Mathematics', 8, 'easy', 1, '2026-10-12 17:20:01') ON CONFLICT DO NOTHING;
INSERT INTO questions (id, text, type, options, correct_answer, explanation, subject, grade_level, difficulty, weight, created_at) VALUES ('q-001', 'What is the capital of France?', 'mcq', '["London","Paris","Berlin","Madrid"]', '1', 'Paris is the capital and largest city of France.', 'Geography', 4, 'easy', 1, '2026-10-12 17:20:01') ON CONFLICT DO NOTHING;
INSERT INTO questions (id, text, type, options, correct_answer, explanation, subject, grade_level, difficulty, weight, created_at) VALUES ('q-002', 'The Great Wall of China was built to protect against invasions from the north.', 'trueFalse', NULL, 'true', 'The Great Wall was constructed over many centuries primarily to defend against invasions and raids from northern nomadic groups.', 'History', 5, 'easy', 1, '2026-10-12 17:20:01') ON CONFLICT DO NOTHING;
INSERT INTO questions (id, text, type, options, correct_answer, explanation, subject, grade_level, difficulty, weight, created_at) VALUES ('q-003', 'What is the chemical symbol for Gold?', 'mcq', '["Go","Gd","Au","Ag"]', '2', 'Au is the chemical symbol for Gold, derived from its Latin name "Aurum".', 'Science', 6, 'medium', 1.5, '2026-10-12 17:20:01') ON CONFLICT DO NOTHING;
INSERT INTO questions (id, text, type, options, correct_answer, explanation, subject, grade_level, difficulty, weight, created_at) VALUES ('q-004', 'Which planet is known as the Red Planet?', 'mcq', '["Venus","Mars","Jupiter","Saturn"]', '1', 'Mars is called the Red Planet because of its reddish appearance due to iron oxide on its surface.', 'Science', 5, 'easy', 1, '2026-10-12 17:20:01') ON CONFLICT DO NOTHING;
INSERT INTO questions (id, text, type, options, correct_answer, explanation, subject, grade_level, difficulty, weight, created_at) VALUES ('q-005', 'Photosynthesis is the process by which plants convert sunlight into chemical energy.', 'trueFalse', NULL, 'true', 'Photosynthesis is indeed the process where plants use sunlight, water, and carbon dioxide to produce glucose and oxygen.', 'Science', 6, 'medium', 1.5, '2026-10-12 17:20:01') ON CONFLICT DO NOTHING;
INSERT INTO questions (id, text, type, options, correct_answer, explanation, subject, grade_level, difficulty, weight, created_at) VALUES ('q-006', 'What is 15% of 200?', 'mcq', '["20","25","30","35"]', '2', '15% of 200 = (15/100) × 200 = 30', 'Mathematics', 6, 'easy', 1, '2026-10-12 17:20:01') ON CONFLICT DO NOTHING;
INSERT INTO questions (id, text, type, options, correct_answer, explanation, subject, grade_level, difficulty, weight, created_at) VALUES ('q-007', 'Solve for x: 2x + 5 = 13', 'mcq', '["2","3","4","5"]', '2', '2x + 5 = 13 → 2x = 8 → x = 4', 'Mathematics', 7, 'medium', 1.5, '2026-10-12 17:20:01') ON CONFLICT DO NOTHING;
INSERT INTO questions (id, text, type, options, correct_answer, explanation, subject, grade_level, difficulty, weight, created_at) VALUES ('q-008', 'The mitochondria is the powerhouse of the cell.', 'trueFalse', NULL, 'true', 'Mitochondria is responsible for producing ATP, which provides energy for cellular functions.', 'Science', 8, 'medium', 1.5, '2026-10-12 17:20:01') ON CONFLICT DO NOTHING;
